input.command:
P="$TMPDIR/probe6"; rm -rf "$P"; mkdir -p "$P/.claude" "$P/sub"
cd "$P" && git init -q . && echo "x" > sub/a.txt
cat > "$P/.claude/mark.sh" <<EOF
#!/bin/bash
echo "FIRED:\$1 cwd=\$(pwd)" >> "$P/marks.log"
EOF
chmod +x "$P/.claude/mark.sh"
cat > "$P/.claude/settings.json" <<EOF
{
  "hooks": {
    "SessionStart": [
      { "hooks": [ { "type": "command", "command": "$P/.claude/mark.sh", "args": ["settings.json"] } ] }
    ]
  }
}
EOF
cat > "$P/.claude/settings.local.json" <<EOF
{
  "hooks": {
    "SessionStart": [
      { "hooks": [ { "type": "command", "command": "$P/.claude/mark.sh", "args": ["settings.local.json"] } ] }
    ]
  }
}
EOF
find "$P" -type f -not -path "*/.git/*" | sort

P=/tmp/claude-501/probe6; rm -f "$P/marks.log"
cat > "$P/.claude/settings.json" <<EOF
{
  "hooks": {
    "SessionStart": [
      { "hooks": [ { "type": "command", "command": "echo FIRED-settings-json >> $P/marks.log" } ] }
    ]
  }
}
EOF
cat > "$P/.claude/settings.local.json" <<EOF
{
  "hooks": {
    "SessionStart": [
      { "hooks": [ { "type": "command", "command": "echo FIRED-settings-local >> $P/marks.log" } ] }
    ]
  }
}
EOF
cd "$P" && claude -p "reply DONE" --model claude-haiku-4-5-20251001 --permission-mode acceptEdits < /dev/null 2>&1 | tail -2
echo "=== repo root 起動 ==="; cat "$P/marks.log" 2>/dev/null || echo "(発火なし)"

P=/tmp/claude-501/probe6; rm -f "$P/marks.log"
echo "# probe6 root memory" > "$P/CLAUDE.md"
cat > "$P/.claude/settings.json" <<EOF
{
  "hooks": {
    "InstructionsLoaded": [
      { "hooks": [ { "type": "command", "command": "echo FIRED-settings-json >> $P/marks.log" } ] }
    ]
  }
}
EOF
cat > "$P/.claude/settings.local.json" <<EOF
{
  "hooks": {
    "InstructionsLoaded": [
      { "hooks": [ { "type": "command", "command": "echo FIRED-settings-local >> $P/marks.log" } ] }
    ]
  }
}
EOF
cd "$P" && claude -p "reply DONE" --model claude-haiku-4-5-20251001 --permission-mode acceptEdits < /dev/null 2>&1 | tail -2
echo "=== A: repo root 起動 ==="; sort -u "$P/marks.log" 2>/dev/null || echo "(発火なし)"
